INSERT INTO public.programs (id, number, icon, accent_color, title, subtitle, tag, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '01', '💼', '#00d4ff', '{"fr":"Développement économique, commerce et emploi","en":"Economic Development, Commerce and Employment","ar":"التنمية الاقتصادية والتجارة والتوظيف"}', '{"fr":"Notre priorité est de transformer Aïn El Turck en une commune créatrice de richesse.","en":"Our priority is to transform Ain El Turck into a wealth-generating communality.","ar":"أولويتنا هي تحويل عين الترك إلى بلدية تُنتج الثروة."}', '{"fr":"Développement Économique","en":"Economic Development","ar":"التنمية الاقتصادية"}', 0);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"L''ouverture d''une deuxième route reliant les deux extrémités de la commune afin de désengorger la circulation.","en":"Opening a second road connecting the two ends of the communality to ease traffic flow.","ar":"فتح طريق ثانٍ يربط طرفي البلدية لتخفيف الازدحام المروري."}', 0);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"La réalisation des raccordements nécessaires sur cette route déjà existante.","en":"Carrying out the necessary connections on this already existing road.","ar":"إنجاز التوصيلات اللازمة على هذا الطريق الموجود بالفعل."}', 1);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"La création d''un nouveau corridor économique favorisant l''implantation de commerces et de nouveaux locaux commerciaux.","en":"Creating a new economic corridor promoting the establishment of businesses and new commercial premises.","ar":"إنشاء ممر اقتصادي جديد يشجع على استقرار المتاجر والمحلات التجارية الجديدة."}', 2);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"La valorisation des terrains, habitations et résidences situés le long de cette nouvelle voie.","en":"Enhancing the value of land, homes and residences located along this new road.","ar":"تعزيز قيمة الأراضي والمساكن والإقامات الواقعة على طول هذا الطريق الجديد."}', 3);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"La création d''emplois directs et indirects.","en":"Creating direct and indirect jobs.","ar":"خلق فرص عمل مباشرة وغير مباشرة."}', 4);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"La création d''un marché quotidien à Trouville (à l''étude).","en":"Creating a daily market in Trouville (under study).","ar":"إنشاء سوق يومي في تروفيل (قيد الدراسة)."}', 5);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"La création d''un marché hebdomadaire de véhicules à l''entrée ou à la sortie de la commune.","en":"Creating a weekly vehicle market at the entrance or exit of the communality.","ar":"إنشاء سوق أسبوعي للمركبات عند مدخل أو مخرج البلدية."}', 6);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"L''installation de kiosques commerciaux harmonisés selon une architecture de style californien.","en":"Installing harmonized commercial kiosks according to California-style architecture.","ar":"تركيب أكشاك تجارية متناسقة وفق هندسة معمارية على الطراز الكاليفورني."}', 7);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"La création d''une base de données recensant tous les commerces, entreprises, artisans, professions libérales, associations, clubs et services de la commune afin de faciliter les échanges économiques et l''accès des citoyens aux services.","en":"Creating a database listing all businesses, companies, craftsmen, liberal professions, associations, clubs and services of the communality to facilitate economic exchanges and citizen access to services.","ar":"إنشاء قاعدة بيانات تسرد جميع المتاجر والمؤسسات والحرفيين والمهن الحرة والجمعيات والأندية والخدمات بالبلدية من أجل تسهيل التبادلات الاقتصادية وللوصول المواطنين إلى الخدمات."}', 8);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"L''organisation de rencontres régulières entre entreprises, commerçants, investisseurs, clubs et associations afin de développer le sponsoring, les partenariats et les projets communs.","en":"Organizing regular meetings between companies, traders, investors, clubs and associations to develop sponsorship, partnerships and joint projects.","ar":"تنظيم لقاءات دورية بين المؤسسات والتجار والمستثمرين والأندية والجمعيات من أجل تطوير الرعاية والشراكات والمشاريع المشتركة."}', 9);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000001', '{"fr":"Encourager, dans le respect de la réglementation, les entreprises titulaires de marchés publics à contribuer à la résolution de deux problématiques d''intérêt communal dans le cadre de leur responsabilité sociétale.","en":"Encouraging, in compliance with regulations, public contract holders to contribute to solving two problems of communal interest as part of their social responsibility.","ar":"تشجيع المؤسسات الحاصلة على صفقات عمومية، في احترام للتنظيم، على المساهمة في حل مشكلتين ذات اهتمام بلدي في إطار مسؤوليتها الاجتماعية."}', 10);
INSERT INTO public.programs (id, number, icon, accent_color, title, subtitle, tag, sort_order) VALUES ('00000000-0000-4000-8000-000000000002', '02', '🚗', '#ff006e', '{"fr":"Mobilité, circulation et transports","en":"Mobility, Traffic and Transport","ar":"التنقل والسير والمواصلات"}', '{"fr":"La mobilité est indispensable au développement économique.","en":"Mobility is essential for economic development.","ar":"التنقل ضروري للتنمية الاقتصادية."}', '{"fr":"Mobilité","en":"Mobility","ar":"التنقل"}', 1);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000002', '{"fr":"L''ouverture de la deuxième route afin de fluidifier durablement la circulation.","en":"Opening the second road to ease traffic flow in the long term.","ar":"فتح الطريق الثاني لتسهيل حركة المرور بشكل دائم."}', 0);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000002', '{"fr":"La création de nouvelles lignes de transport en commun.","en":"Creating new public transport lines.","ar":"إنشاء خطوط جديدة للنقل العمومي."}', 1);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000002', '{"fr":"La création de nouvelles lignes de taxis desservant les quartiers éloignés.","en":"Creating new taxi lines serving remote neighborhoods.","ar":"إنشاء خطوط جديدة للتاكسي تخدم الأحياء النائية."}', 2);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000002', '{"fr":"Une meilleure desserte des quartiers afin que les citoyens n''aient plus à parcourir de longues distances à pied pour rejoindre la route nationale.","en":"Better service to neighborhoods so that citizens no longer have to walk long distances to reach the national road.","ar":"خدمة أفضل للأحياء حتى لا يضطر المواطنون لقطع مسافات طويلة سيراً على الأقدام للوصول إلى الطريق الوطني."}', 3);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000002', '{"fr":"Une meilleure gestion des flux routiers pendant la saison estivale.","en":"Better management of traffic flows during the summer season.","ar":"إدارة أفضل لتدفقات المرور خلال الموسم الصيفي."}', 4);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000002', '{"fr":"Bâtir 6 ponts pour la déviation depuis la route vers les Andalouses et permettre l''accès à la ville d''Aïn El Turck facilement, d''éviter les embouteillages ou encombrements.","en":"Building 6 bridges for the bypass from the road to the Andalouses to allow easy access and avoid traffic jams.","ar":"بناء 6 جسور لتحويل المرور من الطريق نحو الأندلس وتمكين الوصول إلى مدينة عين الترك بسهولة، وتجنب الاختناقات المرورية أو الازدحام."}', 5);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000002', '{"fr":"Création de stations de transport en commun près des agglomérations Trouville, Bouisseville, Bensmir, près des accès de l''autoroute et Cap Falcon, Les Dunes.","en":"Creating public transport stations near the agglomerations Trouville, Bouisseville, Bensmir, near highway access, Cap Falcon, and Les Dunes.","ar":"إنشاء محطات للنقل العمومي بالقرب من التجمعات السكنية تروفيل، بويسفيل، بنسمير، بالقرب من مداخل الطريق السريع وكاب فالكون، ليدون."}', 6);
INSERT INTO public.programs (id, number, icon, accent_color, title, subtitle, tag, sort_order) VALUES ('00000000-0000-4000-8000-000000000003', '03', '🏖️', '#d4af37', '{"fr":"Tourisme, plages et attractivité","en":"Tourism, Beaches and Attractiveness","ar":"السياحة والشواطئ والجاذبية"}', '{"fr":"Aïn El Turck doit de venir une référence nationale parmi les stations balnéaires.","en":"Ain El Turck must become a national reference among seaside resorts.","ar":"يجب أن تصبح عين الترك مرجعاً وطنياً بين المنتجعات البحرية."}', '{"fr":"Tourisme","en":"Tourism","ar":"السياحة"}', 2);
INSERT INTO public.program_items (program_id, text, sort_order) VALUES ('00000000-0000-4000-8000-000000000003', '{"fr":"Des accès aux plages conçus pour durer grâce à la fabrication par l''APC de ses propres moules de murs de style architecture osmanienne.","en":"Beach access designed to last thanks to the APC manufacturing its own Ottoman-style wall molds.","ar":"مداخل شاطئ مصممة لتدوم بفضل تصنيع البلدية لقوالبها الخاصة من جدران على الطراز العثماني."}', 0);
