INSERT INTO public.candidates (id, name, role, party, biography, photo_url, sort_order) VALUES ('00000000-0000-4000-8000-0000000000c1', 'Zenasni Nabil', '{"fr":"Secretaire","en":"Secretary","ar":"الأمين"}', '{"fr":"RND - RND","en":"RND - RND","ar":"التجمع - RND"}', '{"fr":"Une Algerie forte, prospere et unie. Le RND oeuvre pour une gouvernance transparente, une economie dynamique et une transformation numerique au service de tous les citoyens, dans chaque commune du pays.","en":"A strong, prosperous and united Algeria. The RND works for transparent governance, a dynamic economy and digital transformation at the service of all citizens, in every commune of the country.","ar":"جزائر قوية ومزدهرة وموحدة. يعمل التجمع الوطني الديمقراطي من أجل حوكمة شفافة واقتصاد ديناميكي وتحول رقمي في خدمة جميع المواطنين، في كل بلدية من بلديات الوطن."}', 'assets/images/nabil-zenasni-profile2.jpg', 0);
